"""Stored-term Sum2 accumulation and its uniform scalar-error bound.

The call boundary materializes each Float64 input before TwoSum. No global
floating-point mode changes. The bound describes the rounded sum of these
stored terms, not an exact clothoid or an unrounded dot product.
"""

from extensions.carla.curve_interval import _Interval
from std.math import inf, isfinite
from std.memory import bitcast, stack_allocation


@no_inline
def _sum2_update(
    total: Float64, correction: Float64, term: Float64
) -> Tuple[Float64, Float64]:
    # Knuth TwoSum. The six separately rounded additions/subtractions recover
    # the exact residual of total + term, including gradual underflow.
    var high = total + term
    var virtual_term = high - total
    var virtual_total = high - virtual_term
    var total_error = total - virtual_total
    var term_error = term - virtual_term
    var residual = total_error + term_error
    return (high, correction + residual)


@no_inline
def _sum2_supported_environment() -> Bool:
    # Volatile word loads are an invocation-local compiler barrier. They
    # prevent constant folding or cross-call reuse of these arithmetic probes.
    # No process/thread FP control mode is changed or success cached.
    # Like ordinary arithmetic, the probes can set sticky exception flags.
    var one_slot = stack_allocation[1, UInt64]()
    var half_slot = stack_allocation[1, UInt64]()
    var tiny_slot = stack_allocation[1, UInt64]()
    one_slot[unsafe_offset=0] = UInt64(0x3FF0000000000000)
    half_slot[unsafe_offset=0] = UInt64(0x3CA0000000000000)
    tiny_slot[unsafe_offset=0] = UInt64(1)
    var one_word = one_slot.unsafe_load[volatile=True]()
    var one = bitcast[DType.float64](one_word)
    var half = bitcast[DType.float64](half_slot.unsafe_load[volatile=True]())
    var tiny = bitcast[DType.float64](tiny_slot.unsafe_load[volatile=True]())
    var even = _sum2_update(one, 0.0, half)
    var odd = _sum2_update(
        bitcast[DType.float64](one_word + UInt64(1)), 0.0, half
    )
    if bitcast[DType.uint64](even[0]) != UInt64(0x3FF0000000000000) or bitcast[
        DType.uint64
    ](odd[0]) != UInt64(0x3FF0000000000002):
        return False
    var first = _sum2_update(one, 0.0, tiny)
    var last = _sum2_update(first[0], first[1], -one)
    # Compare words: DAZ can make a floating comparison treat eta as zero.
    return bitcast[DType.uint64](last[0] + last[1]) == UInt64(1)


def _require_sum2_environment() raises:
    if not _sum2_supported_environment():
        raise Error(
            "Canonical lane arithmetic requires round-to-nearest and gradual"
            " underflow"
        )


def _sum2_error(magnitude: Float64, inherited: Float64, count: Int) -> Float64:
    if not _sum2_supported_environment():
        return inf[DType.float64]()
    return _sum2_error_checked(magnitude, inherited, count)


def _sum2_error_checked(
    magnitude: Float64, inherited: Float64, count: Int
) -> Float64:
    # Caller has checked the FP environment for this invocation.
    # For every point in the complete input domain, magnitude bounds the sum
    # of absolute stored terms and inherited bounds their total input error.
    # Sum2: |computed - exact sum(stored terms)| <= u*|sum| + gamma_(n-1)^2*M.
    # We conservatively use |sum| <= M. The guarded range keeps the ordinary
    # partial sum, correction and every TwoSum subtraction below overflow.
    if (
        count < 1
        or count > 1073741824
        or not isfinite(magnitude)
        or magnitude < 0.0
        or magnitude > 8.452712498170644e270
        or not isfinite(inherited)
        or inherited < 0.0
    ):
        return inf[DType.float64]()
    if magnitude == 0.0:
        return inherited
    if count == 1:
        return inherited
    var u = _Interval.point(1.1102230246251565e-16)
    var nu = _Interval.point(Float64(count - 1)) * u
    var gamma = nu / (_Interval.point(1.0) - nu)
    return (
        _Interval.point(inherited)
        + (u + gamma * gamma) * _Interval.point(magnitude)
    ).high

functions._lane_spiral:
def _lane_spiral(geometry: RoadGeometry, d: Float64) raises -> DirectedPoint:
    _require_sum2_environment()
    var k0 = geometry.curvature_start
    var rate = (
        geometry.curvature_end - geometry.curvature_start
    ) / geometry.length
    var reach = max(abs(k0), abs(k0 + rate * d))
    var pieces = 1 + Int(ceil(d * (1.0 + reach)))
    var step = d / Float64(pieces)
    var nodes = materialize[_GL_NODES]()
    var weights = materialize[_GL_WEIGHTS]()
    # Accumulate displacement before adding the origin. Repeatedly
    # rounding a large world origin would discard small quadrature terms.
    var x = Float64(0.0)
    var y = Float64(0.0)
    var x_correction = Float64(0.0)
    var y_correction = Float64(0.0)
    for piece in range(pieces):  # pragma: no branch
        var start = step * Float64(piece)
        for i in range(5):  # pragma: no branch
            var t = start + step * 0.5 * (1.0 + nodes[i])
            var theta = geometry.heading + t * (k0 + 0.5 * rate * t)
            # Non-inlined Sum2 calls materialize the complete products.
            # A named intermediate alone would not prevent contraction.
            var next_x = _sum2_update(
                x, x_correction, step * 0.5 * weights[i] * cos(theta)
            )
            var next_y = _sum2_update(
                y, y_correction, step * 0.5 * weights[i] * sin(theta)
            )
            x = next_x[0]
            x_correction = next_x[1]
            y = next_y[0]
            y_correction = next_y[1]
    return DirectedPoint(
        geometry.x + (x + x_correction),
        geometry.y + (y + y_correction),
        0.0,
        geometry.heading + d * (k0 + 0.5 * rate * d),
    )

functions._spiral_expression:
def _spiral_expression[
    derivatives: Bool
](
    geometry: RoadGeometry,
    d: _JetExpression[derivatives],
    pieces: Int,
    translation: Vector3,
) -> Tuple[
    _JetExpression[derivatives],
    _JetExpression[derivatives],
    _JetExpression[derivatives],
]:
    comptime Expression = _JetExpression[derivatives]
    if not _sum2_supported_environment():
        var unknown = Expression(
            _Interval.whole(),
            _Interval.whole(),
            _Interval.whole(),
            inf[DType.float64](),
        )
        return (unknown, unknown, unknown)
    var k0 = Expression.constant(geometry.curvature_start)
    var rate = Expression.constant(
        (geometry.curvature_end - geometry.curvature_start) / geometry.length
    )
    var step = d / Expression.constant(Float64(pieces))
    var nodes = materialize[_GL_NODES]()
    var weights = materialize[_GL_WEIGHTS]()
    var x = Expression.constant(0.0)
    var y = Expression.constant(0.0)
    var x_magnitude = _Interval.point(0.0)
    var y_magnitude = _Interval.point(0.0)
    var x_inherited = _Interval.point(0.0)
    var y_inherited = _Interval.point(0.0)
    var piece = 0
    while piece < pieces:
        var start = step * Expression.constant(Float64(piece))
        var i = 0
        while i < 5:
            var t = start + _stored_half(step) * Expression.constant(
                1.0 + nodes[i]
            )
            var theta = Expression.constant(geometry.heading) + t * (
                k0 + _stored_half(rate) * t
            )
            var trig = _sincos_expression(theta)
            var term_x = (
                _stored_half(step) * Expression.constant(weights[i]) * trig[1]
            )
            var term_y = (
                _stored_half(step) * Expression.constant(weights[i]) * trig[0]
            )
            # The exact-real value and derivatives still describe the same
            # polynomial sum. Scalar error follows the materialized Sum2 graph.
            x = x + term_x
            y = y + term_y
            x_magnitude = x_magnitude + _Interval.point(
                term_x.rounded_value().magnitude()
            )
            y_magnitude = y_magnitude + _Interval.point(
                term_y.rounded_value().magnitude()
            )
            x_inherited = x_inherited + _Interval.point(term_x.error)
            y_inherited = y_inherited + _Interval.point(term_y.error)
            i += 1
        piece += 1
    x.error = _sum2_error_checked(
        x_magnitude.high, x_inherited.high, 5 * pieces
    )
    y.error = _sum2_error_checked(
        y_magnitude.high, y_inherited.high, 5 * pieces
    )
    var heading = Expression.constant(geometry.heading) + d * (
        k0 + _stored_half(rate) * d
    )
    return (
        (
            Expression.constant(geometry.x)
            - Expression.constant(Float64(translation.x))
        )
        + x,
        (
            Expression.constant(geometry.y)
            + Expression.constant(Float64(translation.y))
        )
        + y,
        heading,
    )

functions._lane_jet_model_proof:
def _lane_jet_model_proof[
    capture: Bool
](
    road: Road,
    section: Int,
    lane: Int,
    low: Float64,
    high: Float64,
    translation: Vector3,
    proof: Optional[_SpiralDomainProof],
    root_low: Float64,
    root_high: Float64,
    mut captured: _SpiralRootCapture,
    ideal_translation: Bool = False,
) raises -> Tuple[_Jet, _Jet, _Jet]:
    # A supplied cached proof was captured under a checked arithmetic mode.
    # Recheck this invocation before record/profile selection can reuse it.
    if proof and not _sum2_supported_environment():
        return _unknown_point()
    var geometry_at = info_index(road.info.geometries, low)
    var elevation_at = info_index(road.info.elevations, low)
    var offset_at = info_index(road.info.lane_offsets, low)
    if geometry_at < 0 or elevation_at < 0 or offset_at < 0:
        raise Error("A lane bound needs geometry, elevation and offset records")
    if (
        info_index(road.info.geometries, high) != geometry_at
        or info_index(road.info.elevations, high) != elevation_at
        or info_index(road.info.lane_offsets, high) != offset_at
    ):
        return _unknown_point()
    var s = _Jet.variable(low, high)
    var offset = _Jet.constant(0.0)
    ref lanes = road.sections[section].lanes
    var lane_id = lanes[lane].id
    var negative = lane_id.value < 0
    var sign = _Jet.constant(1.0 if negative else -1.0)
    if lane_id.value != 0:
        var position = 0
        var done = False
        while position < len(lanes) and not done:
            var i = len(lanes) - 1 - position if negative else position
            position += 1
            if negative:
                if lanes[i].id.value >= 0:
                    continue
            elif lanes[i].id.value < 1:
                continue
            var width_at = info_index(lanes[i].info.widths, low)
            if width_at < 0:
                raise Error("A lane bound needs a width record")
            if info_index(lanes[i].info.widths, high) != width_at:
                return _unknown_point()
            var width = _polynomial_jet(
                lanes[i].info.widths[width_at].polynomial, s
            )
            if lanes[i].id != lane_id:
                offset = offset + sign * width
            else:
                offset = offset + _stored_half(sign * width)
                done = True
    offset = offset - _polynomial_jet(
        road.info.lane_offsets[offset_at].polynomial, s
    )
    ref record = road.info.geometries[geometry_at]
    comptime if capture:
        captured.record_at = geometry_at
        captured.low = low
        captured.high = high
    # These branches consume no generic reference result. Keep the same
    # expression graphs without constructing a discarded ARC reference or
    # evaluating the LINE's constant tangent twice.
    if record.geometry.kind == ARC:
        var d = _geometry_distance(
            record.geometry, _stored_difference(s, _Jet.constant(record.s))
        )
        var arc = _arc_offset_jet(record.geometry, d, offset, translation)
        return (
            arc[0],
            arc[1],
            _polynomial_jet(
                road.info.elevations[elevation_at].polynomial,
                s,
                Float64(translation.z),
            ),
        )
    if record.geometry.kind == LINE:
        var d = _geometry_distance(
            record.geometry, _stored_difference(s, _Jet.constant(record.s))
        )
        var trig = _constant_sincos_jet(record.geometry.heading)
        var x = (
            _Jet.constant(record.geometry.x)
            - _Jet.constant(Float64(translation.x))
        ) + d * trig[1]
        var y = (
            _Jet.constant(record.geometry.y)
            + _Jet.constant(Float64(translation.y))
        ) + d * trig[0]
        return (
            x + offset * trig[0],
            y - offset * trig[1],
            _polynomial_jet(
                road.info.elevations[elevation_at].polynomial,
                s,
                Float64(translation.z),
            ),
        )
    var reused: Optional[Tuple[_Jet, _Jet, _Jet]] = None
    comptime if not capture:
        if proof:
            # A proof is zero-translation only. Generic translated expansion
            # retains its existing operation graph and infinite final error.
            if (
                record.geometry.kind == SPIRAL
                and proof.value().record_at == geometry_at
                and (
                    ideal_translation
                    or (
                        translation.x == 0.0
                        and translation.y == 0.0
                        and translation.z == 0.0
                    )
                )
            ):
                var d = _geometry_distance(
                    record.geometry,
                    _stored_difference(s, _Jet.constant(record.s)),
                )
                var counts = _spiral_counts(record.geometry, d)
                if _spiral_proof_matches(
                    proof.value(),
                    record.geometry,
                    geometry_at,
                    low,
                    high,
                    root_low,
                    root_high,
                    d,
                    counts,
                ):
                    var first = _spiral_proof_branch(
                        proof.value(),
                        record.geometry,
                        d,
                        counts[0],
                        translation,
                    )
                    if _finite_spiral_ideal_branch(
                        first
                    ) if ideal_translation else _finite_spiral_moment_branch(
                        first
                    ):
                        if counts[0] == counts[1]:
                            reused = first
                        else:
                            var last = _spiral_proof_branch(
                                proof.value(),
                                record.geometry,
                                d,
                                counts[1],
                                translation,
                            )
                            if _finite_spiral_ideal_branch(
                                last
                            ) if ideal_translation else _finite_spiral_moment_branch(
                                last
                            ):
                                reused = _union_points(first, last)
                    # A nonfinite reordered branch leaves reuse absent. The
                    # original reference below runs under the same already
                    # reserved/debited work; no altered error or union is used.
    var point: Tuple[_Jet, _Jet, _Jet]
    if reused:
        point = reused.value()
    else:
        point = _reference_jet_capture[capture](
            record.geometry,
            _stored_difference(s, _Jet.constant(record.s)),
            translation,
            captured,
        )
    var trig = _sincos_jet(point[2])
    return (
        point[0] + offset * trig[0],
        point[1] - offset * trig[1],
        _polynomial_jet(
            road.info.elevations[elevation_at].polynomial,
            s,
            Float64(translation.z),
        ),
    )

functions._lane_certificate_contains:
def _lane_certificate_contains(
    road: Road,
    section: Int,
    lane: Int,
    location: Vector3,
    mut certificate: _LaneCertificate,
    max_nodes: Int = 16384,
    max_terms: Int = 2000000,
) raises -> Bool:
    _require_sum2_environment()
    var query: Array[Float64, 3] = [
        Float64(location.x),
        Float64(location.y),
        Float64(location.z),
    ]
    if certificate.exact_witness:
        # The returned s is itself a proved minimizer. Use the exact stored
        # point predicate, including strict exclusion of a boundary point.
        if (
            info_index(
                road.sections[section].lanes[lane].info.widths, certificate.s
            )
            < 0
        ):
            raise Error("A lane classification needs a width record")
        return _wide_plan_contains(
            certificate.point,
            query,
            road.lane_width(section, lane, certificate.s),
        )
    if len(certificate.cells) == 0:
        raise Error("Lane classification needs possible minimizing cells")
    if (
        info_index(
            road.sections[section].lanes[lane].info.widths, certificate.s
        )
        < 0
    ):
        raise Error("A lane classification needs a width record")
    # The approximate returned waypoint must agree with every possible
    # minimizing cell. Cell consensus alone does not classify this sample.
    var result = _wide_plan_contains(
        certificate.point, query, road.lane_width(section, lane, certificate.s)
    )
    if len(certificate.cells) > max_nodes - certificate.nodes:
        raise Error("Lane classification exhausted its interval work limit")
    var pending = certificate.cells.copy()
    while len(pending) > 0:
        var cell = pending.pop()
        if certificate.nodes >= max_nodes:
            raise Error("Lane classification exhausted its interval work limit")
        certificate.nodes += 1
        # Width comes first. A near-zero distance certificate can classify
        # its minimizing set without resolving a broad curve/quadrature cell.
        var width = _lane_width_box(road, section, lane, cell.low, cell.high)
        if not width.is_finite():
            raise Error("Lane classification needs a finite width enclosure")
        var minimum_upper = _minimizer_plan_width_upper(
            width, certificate.upper, certificate.scale
        )
        var resolved: Optional[Bool]
        if width.high <= 0.0:
            resolved = False
        elif width.low > 0.0 and minimum_upper < 0.0:
            resolved = True
        elif cell.low == cell.high:
            var point = _checked_center(
                road, section, lane, cell.low, certificate.terms, max_terms
            )
            resolved = _wide_plan_contains(
                point, query, road.lane_width(section, lane, cell.low)
            )
        else:
            var work = _reference_work(road, cell.low, cell.high)
            if work < 0:
                raise Error(
                    "Lane classification cannot resolve a minimizing cell"
                )
            if certificate.terms > max_terms - work:
                raise Error(
                    "Lane classification exhausted its quadrature work limit"
                )
            certificate.terms += work
            var point = _lane_jet(road, section, lane, cell.low, cell.high)
            # A strict 3D lower bound can remove this entire cell from the
            # minimizing set before its planar classification is resolved.
            if (
                _scaled_point_distance_box(
                    point, location, certificate.scale
                ).low
                > certificate.upper
            ):
                continue
            var full_difference = _scaled_plan_width_box(
                point, width, location, certificate.scale
            )
            var restricted_high = min(full_difference.high, minimum_upper)
            if full_difference.low > restricted_high:
                # These bounds prove this cell has no exact minimizing point.
                # It cannot constrain classification of the minimizing set.
                continue
            var minimizing_difference = _Interval(
                full_difference.low, restricted_high
            )
            resolved = _plan_box_classification(width, minimizing_difference)
        if not Bool(resolved):
            var middle = _midpoint(cell.low, cell.high)
            if middle <= cell.low or middle >= cell.high or cell.depth >= 96:
                raise Error(
                    "Lane classification is unresolved over a possible"
                    " minimizing cell"
                )
            # A loose minimum certificate need not be a loose classification
            # result. Both closed halves cover the original cell; subdivision
            # uses the SAME cumulative node/term ledger and retained depth.
            pending.append(
                _ClosedInterval(
                    middle, cell.high, cell.depth + 1, cell.lower, cell.scale
                )
            )
            pending.append(
                _ClosedInterval(
                    cell.low, middle, cell.depth + 1, cell.lower, cell.scale
                )
            )
            continue
        if result != resolved.value():
            raise Error(
                "Lane classification disagrees across possible minimizing cells"
            )
    return result

functions._closest_lane_certificate:
def _closest_lane_certificate(
    self,
    location: Vector3,
    lane_type: LaneType,
    budget: MapQueryBudget = MapQueryBudget(),
) raises -> Optional[Tuple[Waypoint, _LaneCertificate]]:
    var work = _MapQueryWork(budget)
    return self._closest_lane_certificate_with_work(
        location, lane_type, work
    )

